def make_key_event(key_code, down_keys=(), char_code=0):
    key_states = [0] * 256
    for code in down_keys:
        key_states[code] = 0x80
    return KeyEvent(
        {
            "charCode": char_code,
            "keyCode": key_code,
            "repeatCount": 1,
            "scanCode": 0,
            "isExtended": False,
            "keyStates": key_states,
        }
    )


