class CinbaseShiftSwitchTests(unittest.TestCase):
    def setUp(self):
        self.ts = DummyCinBaseService()
        self.cin_table = MagicMock()
        self.cin_table.loading = False

    def _press_and_release_shift(self, side_vk):
        down_ev = make_key_event(VK_SHIFT, (VK_SHIFT, side_vk))
        up_ev = make_key_event(VK_SHIFT, ())
        CinBase.filterKeyDown(self.ts, down_ev, self.cin_table, None, None)
        return CinBase.filterKeyUp(self.ts, up_ev), up_ev

    def test_both_shift_toggles_in_filter_key_up_without_on_key_up(self):
        self.ts.cfg.switchLangWithWhichShift = SWITCH_LANG_WITH_BOTH_SHIFT

        eaten, _ = self._press_and_release_shift(VK_LSHIFT)
        self.assertFalse(eaten)
        self.assertEqual(self.ts.langMode, ENGLISH_MODE)

        eaten, _ = self._press_and_release_shift(VK_RSHIFT)
        self.assertFalse(eaten)
        self.assertEqual(self.ts.langMode, CHINESE_MODE)

    def test_left_shift_only_uses_key_event_state(self):
        self.ts.cfg.switchLangWithWhichShift = SWITCH_LANG_WITH_LEFT_SHIFT

        # Right shift should not toggle
        eaten, _ = self._press_and_release_shift(VK_RSHIFT)
        self.assertFalse(eaten)
        self.assertEqual(self.ts.langMode, CHINESE_MODE)

        # Left shift should toggle
        eaten, _ = self._press_and_release_shift(VK_LSHIFT)
        self.assertFalse(eaten)
        self.assertEqual(self.ts.langMode, ENGLISH_MODE)

    def test_right_shift_only_uses_key_event_state(self):
        self.ts.cfg.switchLangWithWhichShift = SWITCH_LANG_WITH_RIGHT_SHIFT

        # Left shift should not toggle
        eaten, _ = self._press_and_release_shift(VK_LSHIFT)
        self.assertFalse(eaten)
        self.assertEqual(self.ts.langMode, CHINESE_MODE)

        # Right shift should toggle
        eaten, _ = self._press_and_release_shift(VK_RSHIFT)
        self.assertFalse(eaten)
        self.assertEqual(self.ts.langMode, ENGLISH_MODE)

    def test_prompt_message_does_not_double_toggle_when_filter_key_up_called_twice(self):
        self.ts.hidePromptMessages = False
        self.ts.cfg.switchLangWithWhichShift = SWITCH_LANG_WITH_BOTH_SHIFT

        # Simulates TSF OnTestKeyUp -> OnKeyUp (which calls filterKeyUp again) -> onKeyUp
        eaten_test, up_ev = self._press_and_release_shift(VK_LSHIFT)
        self.assertTrue(eaten_test)
        self.assertEqual(self.ts.langMode, ENGLISH_MODE)

        eaten_on, _ = CinBase.filterKeyUp(self.ts, up_ev), up_ev
        self.assertTrue(eaten_on)
        self.assertEqual(self.ts.langMode, ENGLISH_MODE)

        CinBase.onKeyUp(self.ts, up_ev)
        self.assertEqual(self.ts.langMode, ENGLISH_MODE)
        self.assertFalse(self.ts.isLangModeChanged)
        self.assertIn("showMessage", self.ts.currentReply)

    def test_stale_last_key_down_time_does_not_block_shift(self):
        # Simulate a prior keydown whose keyup was never delivered
        other_down = make_key_event(ord("A"), (ord("A"),), char_code=ord("a"))
        CinBase.filterKeyDown(self.ts, other_down, self.cin_table, None, None)
        self.ts.lastKeyDownTime = time.time() - 5.0

        eaten, _ = self._press_and_release_shift(VK_LSHIFT)
        self.assertFalse(eaten)
        self.assertEqual(self.ts.langMode, ENGLISH_MODE)

    def test_held_shift_over_threshold_does_not_toggle(self):
        down_ev = make_key_event(VK_SHIFT, (VK_SHIFT, VK_LSHIFT))
        up_ev = make_key_event(VK_SHIFT, ())

        CinBase.filterKeyDown(self.ts, down_ev, self.cin_table, None, None)
        self.ts.lastKeyDownTime = time.time() - 1.0
        # Repeated keydown while holding Shift must not reset lastKeyDownTime
        CinBase.filterKeyDown(self.ts, down_ev, self.cin_table, None, None)

        eaten = CinBase.filterKeyUp(self.ts, up_ev)
        self.assertFalse(eaten)
        self.assertEqual(self.ts.langMode, CHINESE_MODE)

    def test_on_deactivate_and_on_preserved_key_reset_key_state(self):
        down_ev = make_key_event(VK_SHIFT, (VK_SHIFT, VK_LSHIFT))
        CinBase.filterKeyDown(self.ts, down_ev, self.cin_table, None, None)
        CinBase.onDeactivate(self.ts)
        self.assertEqual(self.ts.lastKeyDownTime, 0.0)
        self.assertIsNone(self.ts.lastKeyEvent)

        CinBase.filterKeyDown(self.ts, down_ev, self.cin_table, None, None)
        CinBase.onPreservedKey(self.ts, "{00000000-0000-0000-0000-000000000000}")
        self.assertEqual(self.ts.lastKeyDownTime, 0.0)
        self.assertIsNone(self.ts.lastKeyEvent)


